.kb{width:100%;max-width:980px;padding:0;overflow:hidden}
.kb-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px 10px}
.kb-t{margin-top:2px;font-size:16px;font-weight:600;color:var(--text)}
.kb-hr{display:flex;align-items:center;gap:10px}
.kb-avs{display:flex}
.kb-avs .dz-av{margin-left:-6px;box-shadow:0 0 0 2px var(--panel)}
.kb-avs .dz-av:first-child{margin-left:0}
.kb-filters{display:flex;flex-wrap:wrap;gap:6px;padding:0 16px 12px}
.kb-chip{height:28px;padding:0 11px;border:1px solid var(--line);background:var(--panel);font-size:12.5px;font-weight:500;color:var(--text-dim);transition:background-color .2s,color .2s,border-color .2s}
.kb-chip:hover{color:var(--text);border-color:var(--icon-line)}
.kb-chip.on{background:var(--text);border-color:var(--text);color:var(--panel)}
.kb-cols{display:grid;grid-template-columns:repeat(4,minmax(180px,1fr));gap:10px;padding:0 16px 16px;overflow-x:auto}
.kb-col{display:flex;flex-direction:column;gap:8px;min-height:220px;padding:10px;background:var(--bg);border:1px solid transparent;transition:background-color .2s,border-color .2s}
.kb-col.over{border-color:var(--accent);background:var(--accent-bg)}
.kb-ch{display:flex;align-items:center;gap:8px;padding:2px 2px 4px;font-size:13px;font-weight:600;color:var(--text)}
.kb-ch i{width:8px;height:8px;flex:none;background:var(--c)}
.kb-n{margin-left:auto;padding:0 7px;border:1px solid var(--line);background:var(--panel);font-family:var(--mono);font-size:11px;font-weight:700;color:var(--text-dim)}
.kb-list{display:flex;flex-direction:column;gap:8px;flex:1}
.kb-card{display:flex;flex-direction:column;gap:10px;padding:12px;background:var(--panel);border:1px solid var(--line);cursor:grab;transition:border-color .2s,box-shadow .2s,opacity .2s}
.kb-card:hover{border-color:var(--icon-line);box-shadow:0 8px 20px -14px rgba(17,19,24,.35)}
.kb-card.drag{opacity:.35}
.kb-card.hide{display:none}
.kb-tags{display:flex;flex-wrap:wrap;gap:4px}
.kb-tag{display:inline-flex;align-items:center;gap:5px;padding:2px 7px;font-family:var(--mono);font-size:10.5px;font-weight:700;text-transform:uppercase;color:color-mix(in srgb,var(--tone) 78%,var(--text));background:color-mix(in srgb,var(--tone) 12%,var(--panel))}
.kb-tag.design{--tone:#7c5cff}.kb-tag.dev{--tone:#116ff8}.kb-tag.copy{--tone:#d98a00}.kb-tag.qa{--tone:#e5484d}.kb-tag.web{--tone:#159a63}.kb-tag.marketing{--tone:#0ea5a4}
.kb-ct{font-size:13.5px;font-weight:600;line-height:1.35;color:var(--text)}
.kb-done .kb-ct{color:var(--text-dim);text-decoration:line-through;text-decoration-color:var(--muted)}
.kb-prog{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted)}
.kb-prog b{flex:1;height:4px;background:var(--line);position:relative;overflow:hidden}
.kb-prog b i{position:absolute;inset:0 auto 0 0;width:var(--p);background:var(--accent-hi)}
.kb-meta{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)}
.kb-due{white-space:nowrap;display:inline-flex;align-items:center;gap:4px;padding:1px 6px;border:1px solid var(--line);font-size:11.5px;font-weight:600;color:var(--text-dim)}
.kb-due.late{border-color:color-mix(in srgb,#e5484d 40%,transparent);color:#e5484d;background:color-mix(in srgb,#e5484d 8%,transparent)}
.kb-due .ms{font-size:13px}
.kb-meta .kb-cm{display:inline-flex;align-items:center;gap:3px}
.kb-meta .kb-cm .ms{font-size:13px}
.kb-who{display:flex;margin-left:auto}
.kb-who .dz-av,.kb-who .dz-av img{width:22px;height:22px}
.kb-who .dz-av{margin-left:-5px;box-shadow:0 0 0 2px var(--panel)}
.kb-who .dz-av:first-child{margin-left:0}
.kb-pri{width:8px;height:8px;border-radius:50%;background:#e5484d;box-shadow:0 0 0 3px color-mix(in srgb,#e5484d 18%,transparent)}
.kb-new{padding:10px;border:1px dashed var(--icon-line);font-size:12.5px;font-weight:500;color:var(--muted);text-align:left;transition:color .2s,border-color .2s}
.kb-new:hover{color:var(--text);border-color:var(--text-dim)}
[data-style="soft"] .kb{border-radius:22px}
[data-style="soft"] .kb-chip{border-radius:999px}
[data-style="soft"] .kb-chip.on{background:var(--ink);border-color:var(--ink);color:#fff}
[data-style="soft"] .kb-col{border-radius:16px}
[data-style="soft"] .kb-ch i{border-radius:50%}
[data-style="soft"] .kb-n{border-radius:999px;font-family:var(--sans);font-weight:600}
[data-style="soft"] .kb-card{border-radius:14px}
[data-style="soft"] .kb-tag{border-radius:999px;font-family:var(--sans);text-transform:none;font-size:11.5px;font-weight:600}
[data-style="soft"] .kb-prog{font-family:var(--sans);font-weight:600}
[data-style="soft"] .kb-prog b,[data-style="soft"] .kb-prog b i{border-radius:999px}
[data-style="soft"] .kb-due{border-radius:999px}
[data-style="soft"] .kb-new{border-radius:12px}
.kb-ct-w{display:flex;align-items:flex-start;gap:6px}
.kb-ct-w .kb-ct{flex:1;min-width:0;cursor:text;outline:0}
.kb-ct.editing{padding:2px 4px;margin:-2px -4px;background:var(--bg);box-shadow:inset 0 0 0 1px var(--icon-line)}
.kb-ed{display:grid;place-items:center;width:22px;height:22px;flex:none;color:var(--muted);opacity:0;transition:opacity .2s,color .2s}
.kb-card:hover .kb-ed{opacity:1}
.kb-ed:hover{color:var(--text)}
[data-style="soft"] .kb-ct.editing{border-radius:6px}
[data-style="soft"] .kb-ed{border-radius:6px}

