{
  const root = $('#kb'), colsEl = $('#kb-cols');
  const COLS = [['To do','#8a8f99'],['In progress','var(--accent-hi)'],['Review','#7c5cff'],['Done','#159a63']];
  const CARDS = [
    [0,'Write the onboarding emails',['copy'],'Oct 9',2,['Priya Nair'],0,null],
    [0,'Pricing page hero',['design','web'],'Oct 10',0,['Maya Chen'],0,null],
    [1,'Agent status components',['design','dev'],'Oct 8',5,['Maya Chen','Oscar Lind'],1,[3,5]],
    [1,'Checkout flow QA',['qa'],'Today',1,['Jonas Weber'],1,null],
    [2,'Launch announcement',['copy','marketing'],'Oct 12',4,['Ines Duarte'],0,null],
    [2,'Token export to code',['dev'],'Oct 11',0,['Oscar Lind'],0,[4,4]],
    [3,'Brand refresh',['design'],'Oct 2',6,['Maya Chen','Tom Becker'],0,null]
  ];
  const card = ([c, t, tags, due, cm, who, pri, prog]) => `<div class="kb-card ${c === 3 ? 'kb-done' : ''}" draggable="true" data-tags="${tags.join(' ')}" data-who="${who.join(',')}">
    <div class="kb-tags">${tags.map(x => `<span class="kb-tag ${x}">${x === 'qa' ? 'QA' : x[0].toUpperCase() + x.slice(1)}</span>`).join('')}</div>
    <div class="kb-ct-w"><div class="kb-ct" title="Double-click to rename">${t}</div><button class="kb-ed" aria-label="Rename card">${ic('edit_note','sm')}</button></div>${prog ? `<div class="kb-prog"><b><i style="--p:${prog[0] / prog[1] * 100}%"></i></b>${prog[0]}/${prog[1]}</div>` : ''}
    <div class="kb-meta">${pri ? '<span class="kb-pri" title="High priority"></span>' : ''}<span class="kb-due ${due === 'Today' ? 'late' : ''}">${ic(c === 3 ? 'check' : 'calendar','sm')}${due}</span>${cm ? `<span class="kb-cm">${ic('chat_bubble','sm')}${cm}</span>` : ''}<span class="kb-who">${who.map(n => avatar(n)).join('')}</span></div></div>`;
  colsEl.innerHTML = COLS.map(([n, c], i) => `<div class="kb-col" data-c="${i}" style="--c:${c}"><div class="kb-ch"><i></i>${n}<span class="kb-n"></span></div><div class="kb-list">${CARDS.filter(x => x[0] === i).map(card).join('')}</div>${i === 0 ? '<button class="kb-new">+ New card</button>' : ''}</div>`).join('');
  $('#kb-avs').innerHTML = ['Maya Chen','Oscar Lind','Priya Nair','Jonas Weber'].map(n => avatar(n)).join('');
  hydrate(root);
  const count = () => $$('.kb-col', root).forEach(col => { col.querySelector('.kb-n').textContent = $$('.kb-card:not(.hide)', col).length; });
  count();
  // filters
  $('#kb-f').addEventListener('click', e => { const b = e.target.closest('.kb-chip'); if (!b) return; $$('.kb-chip', root).forEach(x => x.classList.toggle('on', x === b)); const f = b.dataset.f;
    $$('.kb-card', root).forEach(cd => { const show = f === 'all' || (f === 'mine' ? cd.dataset.who.includes('Maya Chen') : cd.dataset.tags.split(' ').includes(f)); if (show && cd.classList.contains('hide')){ cd.classList.remove('hide'); if (!reduce) cd.animate([{ opacity:0, transform:'translateY(6px)' }, { opacity:1, transform:'none' }], { duration:300, easing:'cubic-bezier(.16,1,.3,1)' }); } else if (!show) cd.classList.add('hide'); });
    count(); Sound.play('tab'); });
  // drag between columns, cards glide into place
  let drag = null;
  root.addEventListener('dragstart', e => { const c = e.target.closest('.kb-card'); if (!c) return; drag = c; e.dataTransfer.effectAllowed = 'move'; setTimeout(() => c.classList.add('drag'), 0); e.stopPropagation(); });
  root.addEventListener('dragend', () => { if (drag) drag.classList.remove('drag'); drag = null; $$('.kb-col', root).forEach(c => c.classList.remove('over')); });
  root.addEventListener('dragover', e => { const col = e.target.closest('.kb-col'); if (!col || !drag) return; e.preventDefault(); $$('.kb-col', root).forEach(c => c.classList.toggle('over', c === col)); });
  root.addEventListener('drop', e => { const col = e.target.closest('.kb-col'); if (!col || !drag) return; e.preventDefault();
    const list = col.querySelector('.kb-list'), after = [...list.children].find(c => c !== drag && e.clientY < c.getBoundingClientRect().top + c.offsetHeight / 2);
    const before = new Map($$('.kb-card', root).map(c => [c, c.getBoundingClientRect()]));
    list.insertBefore(drag, after || null); drag.classList.toggle('kb-done', col.dataset.c === '3');
    before.forEach((r, c) => { const n = c.getBoundingClientRect(); if (!reduce && (Math.abs(r.left - n.left) > 1 || Math.abs(r.top - n.top) > 1)) c.animate([{ transform:`translate(${r.left - n.left}px,${r.top - n.top}px)` }, { transform:'none' }], { duration:420, easing:'cubic-bezier(.16,1,.3,1)' }); });
    count(); Sound.play(col.dataset.c === '3' ? 'done' : 'pop'); if (col.dataset.c === '3') showToast(`${drag.querySelector('.kb-ct').textContent} moved to Done`); });
  $('#kb-add').addEventListener('click', () => { const list = $('.kb-col[data-c="0"] .kb-list', root); list.insertAdjacentHTML('afterbegin', card([0,'New card',['design'],'Oct 14',0,['Maya Chen'],0,null])); const c = list.firstElementChild; hydrate(c); if (!reduce) c.animate([{ opacity:0, transform:'translateY(-8px) scale(.98)' }, { opacity:1, transform:'none' }], { duration:380, easing:'cubic-bezier(.16,1,.3,1)' }); count(); Sound.play('pop'); });
  $('.kb-new', root).addEventListener('click', () => $('#kb-add').click());
  // rename a card: double-click its title or press the pencil, Enter saves and Escape cancels
  const edit = t => { if (t.isContentEditable) return; const was = t.textContent; t.contentEditable = 'true'; t.closest('.kb-card').draggable = false; t.classList.add('editing'); t.focus();
    const r = document.createRange(); r.selectNodeContents(t); const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r); Sound.play('tick');
    const done = keep => { t.contentEditable = 'false'; t.classList.remove('editing'); t.closest('.kb-card').draggable = true; const v = t.textContent.trim(); if (!keep || !v) t.textContent = was; else if (v !== was){ t.textContent = v; Sound.play('pop'); } t.removeEventListener('keydown', key); t.removeEventListener('blur', blur); };
    const key = e => { if (e.key === 'Enter'){ e.preventDefault(); t.blur(); } if (e.key === 'Escape'){ e.preventDefault(); done(false); } };
    const blur = () => done(true);
    t.addEventListener('keydown', key); t.addEventListener('blur', blur); };
  root.addEventListener('dblclick', e => { const t = e.target.closest('.kb-ct'); if (t) edit(t); });
  root.addEventListener('click', e => { const b = e.target.closest('.kb-ed'); if (b){ e.stopPropagation(); edit(b.parentElement.querySelector('.kb-ct')); } });
}
